    updateSoftKillThreatManager(SIM_FIXED_DT);wip118BuildEngagementControl({commit:true,force:true});updateWip119EngagementAutomation(true);
    const statuses=wip119AutonomyState.candidateRows??[],status=statuses.find(s=>s.row?.trackId===selectedLockId)??statuses.find(s=>s.ready);
    if(!status?.ready){const reason=status?.reason??'NO_READY_RECOMMENDATION';notify(`반자동 발사 보류 · ${status?.text??reason}`);return {ok:false,reason,status:status?{trackId:status.row?.trackId,weapon:status.row?.weapon,text:status.text}:null};}
    const row=status.row,d=wip119WeaponDescriptor(row.weapon);if(!d)return {ok:false,reason:'NOT_VLS'};
    const reserve=wip119ReserveAvailable(row.weapon,1);if(!reserve.ok){notify(`반자동 발사 보류 · ${wip119ReasonText('RESERVE',row,reserve)}`);return {ok:false,reason:'RESERVE',reserve};}
    const gate=trackEngagementGateA3(row.trackId,{automatic:false,mode:'SEMIAUTO'});if(!gate.ok){notify(`반자동 발사 차단 · ${trackA3ReasonKo(gate.reason)}`);return {ok:false,reason:'A3_'+gate.reason,gate};}
    if(d.requiresIlluminator&&!row.firePlan?.reservation){notify('반자동 발사 보류 · NO_CHANNEL');return {ok:false,reason:'NO_CHANNEL'};}
    wip119SetOwnedLock(row.trackId);const before=missiles.length,result=wip121WithDecisionTrack(row.trackId,()=>d.fire({automatic:false,mode:'SEMIAUTO'}));
    if(result===null||missiles.length<=before)return {ok:false,reason:'FIRE_REJECTED'};
    const entry={t:wip119NowS(),trackId:row.trackId,weapon:row.weapon,missileId:missiles.at(-1)?.id??null,mode:'SEMIAUTO',operatorRelease:true};wip119AutonomyState.operatorFireLog.push(entry);if(wip119AutonomyState.operatorFireLog.length>256)wip119AutonomyState.operatorFireLog.shift();wip119AutonomyState.lastAction=`SEMI FIRE ${d.label} → ${trackDisplayLabelById(row.trackId)}`;notify(`반자동 발사 승인 · ${d.label} → ${trackDisplayLabelById(row.trackId)}`);return {ok:true,entry};
  }

